mapper.select:
select ti.*, t.name teacherName, c.name courseName from teaching ti left join teacher t on ti.teacher_id = t.id left join course c on ti.course_id = c.id
ti.semester like concat('%',#{semester},'%') and ti.teacher_id = #{teacherId} and ti.course_id = #{courseId}
order by ti.semester asc

mapper.update:
UPDATE teaching

    teacher_id = #{teacherId},
    course_id = #{courseId},
    semester = #{semester}

WHERE id = #{id}
